const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
function split(element){[...element.childNodes].forEach(node=>{if(node.nodeType===3){const fragment=document.createDocumentFragment();node.textContent.split(/(\s+)/).forEach(word=>{if(!word)return;if(/^\s+$/.test(word)){fragment.append(document.createTextNode(word));return}const wrap=document.createElement('span');wrap.className='premium-word';[...word].forEach(letter=>{const span=document.createElement('span');span.className='premium-letter';span.textContent=letter;wrap.append(span)});fragment.append(wrap)});node.replaceWith(fragment)}else if(node.nodeType===1&&node.tagName!=='BR')split(node)})}
const headings=all('.range-heading h2, .distributor h2, .contact h2, .material-copy h2');headings.forEach(h=>{const original=h.textContent.replace(/\s+/g,' ').trim();h.setAttribute('aria-label',original);split(h);h.querySelectorAll('.premium-word').forEach(w=>w.setAttribute('aria-hidden','true'))});
let frame=0;const clamp=(v)=>Math.max(0,Math.min(1,v)),ease=v=>{v=clamp(v);return v*v*(3-2*v)};
function update(){frame=0;if(reducedMotion)return;headings.forEach(h=>{const rect=h.getBoundingClientRect(),hp=clamp((innerHeight*.92-rect.top)/(innerHeight*.48));const letters=[...h.querySelectorAll('.premium-letter')];letters.forEach((span,i)=>{const k=ease((hp-i/Math.max(1,letters.length)*.35)/.62);span.style.opacity=.24+k*.76;span.style.transform=`translateY(${(1-k)*12}px)`})});
const bridge=$('.material-bridge'),br=bridge.getBoundingClientRect(),bp=clamp((innerHeight-br.top)/(innerHeight+br.height));$('.material-image').style.clipPath=`ellipse(${35+bp*65}% ${55+bp*45}% at ${85-bp*35}% 50%)`;$('.material-image').style.transform=`scale(${1.08-bp*.05})`;$('.material-copy').style.transform=`translateY(${(bp-.5)*-35}px)`;
}
addEventListener('scroll',()=>{if(!frame)frame=requestAnimationFrame(update)},{passive:true});addEventListener('resize',()=>{if(!frame)frame=requestAnimationFrame(update)},{passive:true});update();
